        // ── sequences ──

        static IList<T> AsList<T>(IEnumerable<T> seq) => seq as IList<T> ?? seq.ToList();

        public T choice<T>(IEnumerable<T> seq)
        {
            var list = AsList(seq);
            if (list.Count == 0) throw new IndexOutOfRangeException("Cannot choose from an empty sequence");
            return list[(int)RandBelow(list.Count)];
