        public string choice(string s)
        {
            if (s.Length == 0) throw new IndexOutOfRangeException("Cannot choose from an empty sequence");
            return s[(int)RandBelow(s.Length)].ToString();
        }

        public void shuffle<T>(IList<T> x)
        {
            for (int i = x.Count - 1; i > 0; i--)
            {
                int j = (int)RandBelow(i + 1);
                (x[i], x[j]) = (x[j], x[i]);
            }
        }

        public List<T> sample<T>(IEnumerable<T> population, long k)
        {
            var pop = AsList(population);
            int n = pop.Count;
            if (k < 0 || k > n) throw new ArgumentException("Sample larger than population or is negative");
            var result = new T[k];
            int setsize = 21;
            if (k > 5) setsize += (int)Math.Pow(4, Math.Ceiling(Math.Log(k * 3) / Math.Log(4)));
            if (n <= setsize)
            {
                var pool = pop.ToList();
                for (int i = 0; i < k; i++)
                {
                    int j = (int)RandBelow(n - i);
                    result[i] = pool[j];
                    pool[j] = pool[n - i - 1];
                }
            }
            else
            {
                var selected = new HashSet<long>();
                for (int i = 0; i < k; i++)
                {
                    long j = RandBelow(n);
                    while (selected.Contains(j)) j = RandBelow(n);
                    selected.Add(j);
                    result[i] = pop[(int)j];
                }
            }
            return result.ToList();
        }

        public List<string> sample(string population, long k) => sample(population.Select(c => c.ToString()), k);

        static List<double> Doubles(IEnumerable xs) => xs.Cast<object>().Select(x => Convert.ToDouble(x, System.Globalization.CultureInfo.InvariantCulture)).ToList();

        public List<T> choices<T>(IEnumerable<T> population, IEnumerable? weights = null, IEnumerable? cum_weights = null, long k = 1)
        {
            var pop = AsList(population);
            int n = pop.Count;
            var result = new List<T>((int)Math.Max(0, k));
            if (cum_weights == null)
            {
                if (weights == null)
                {
                    double nf = n;
                    for (long i = 0; i < k; i++) result.Add(pop[(int)Math.Floor(random() * nf)]);
                    return result;
                }
                var cum = new List<double>();
                double acc = 0;
                foreach (var w in Doubles(weights)) cum.Add(acc += w);
                return Pick(cum);
            }
            if (weights != null) throw new InvalidCastException("Cannot specify both weights and cumulative weights");
            return Pick(Doubles(cum_weights));

            List<T> Pick(List<double> cum)
            {
                if (cum.Count != n) throw new ArgumentException("The number of weights does not match the population");
                double total = cum[cum.Count - 1] + 0.0;
                if (total <= 0.0) throw new ArgumentException("Total of weights must be greater than zero");
                if (double.IsInfinity(total) || double.IsNaN(total)) throw new ArgumentException("Total of weights must be finite");
                int hi = n - 1;
                for (long i = 0; i < k; i++)
                {
                    double x = random() * total;
                    int lo = 0, h = hi; // bisect_right(cum, x, 0, hi)
                    while (lo < h) { int mid = (lo + h) / 2; if (x < cum[mid]) h = mid; else lo = mid + 1; }
                    result.Add(pop[lo]);
                }
                return result;
            }
        }

