        public double expovariate(double lambd = 1.0) => -Math.Log(1.0 - random()) / lambd;
        public double paretovariate(double alpha) => Math.Pow(1.0 - random(), -1.0 / alpha);
        public double weibullvariate(double alpha, double beta) => alpha * Math.Pow(-Math.Log(1.0 - random()), 1.0 / beta);

        public double gammavariate(double alpha, double beta)
        {
            if (alpha <= 0.0 || beta <= 0.0) throw new ArgumentException("gammavariate: alpha and beta must be > 0.0");
            if (alpha > 1.0)
            {
