                    if (!(1e-7 < u1 && u1 < 0.9999999)) continue;
                    double u2 = 1.0 - random();
                    double v = Math.Log(u1 / (1.0 - u1)) / ainv;
                    double x = alpha * Math.Exp(v);
                    double z = u1 * u1 * u2;
                    double r = bbb + ccc * v - x;
                    if (r + SgMagic - 4.5 * z >= 0.0 || r >= Math.Log(z)) return x * beta;
                }
            }
            if (alpha == 1.0) return -Math.Log(1.0 - random()) * beta;
            double xx;
            while (true)
            {
                double u = random();
                double b = (Math.E + alpha) / Math.E;
                double p = b * u;
                xx = p <= 1.0 ? Math.Pow(p, 1.0 / alpha) : -Math.Log((b - p) / alpha);
                double u1 = random();
                if (p > 1.0) { if (u1 <= Math.Pow(xx, alpha - 1.0)) break; }
                else if (u1 <= Math.Exp(-xx)) break;
            }
            return xx * beta;
        }

        public double betavariate(double alpha, double beta)
        {
