namespace Typhon.Stdlib
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Numerics;
    using Typhon.Runtime;

    internal static class _random
    {
        internal class Random
        {
            readonly PyRandom _engine = new PyRandom();

            public Random(object? seed = null)
            {
                if (seed != null) _engine.SeedCore(seed);
            }

            public void seed(object? n = null) => _engine.SeedCore(n);
            public virtual double random() => _engine.random();
            public virtual dynamic getstate() => _engine.CoreState();
            public virtual void setstate(dynamic? state) => _engine.RestoreCoreState((object?)state);

            public virtual dynamic getrandbits(dynamic? k)
            {
                object bits = Builtins.__index_value((object?)k);
                BigInteger count = PyRandom.CoreInteger(bits);
                if (count.Sign < 0) throw new ArgumentException("Cannot convert negative int");
                return count <= 63 ? (object)_engine.getrandbits((long)count) : _engine.getrandbits(count);
            }
        }
    }

    /// <summary>The random module: functions of one shared generator, and random.Random(seed) for others.</summary>
    internal static class random_
    {
        static readonly PyRandom _inst = new PyRandom();

        public static PyRandom Random(object? x = null) => new PyRandom(x);
        public static PyRandom SystemRandom(object? x = null) => new PyRandom(system: true);

        public static void seed() => _inst.seed();
        public static void seed(object? a, long version = 2) => _inst.seed(a, version);
        public static object getstate() => _inst.getstate();
        public static void setstate(object state) => _inst.setstate(state);
        public static double random() => _inst.random();
        public static long getrandbits(long k) => _inst.getrandbits(k);
        public static BigInteger getrandbits(BigInteger k) => _inst.getrandbits(k);
        public static long randrange(long stop) => _inst.randrange(stop);
        public static long randrange(long start, long stop, long step = 1) => _inst.randrange(start, stop, step);
        public static BigInteger randrange(BigInteger stop) => _inst.randrange(stop);
        public static BigInteger randrange(BigInteger start, BigInteger stop, BigInteger? step = null) => _inst.randrange(start, stop, step);
        public static long randint(long a, long b) => _inst.randint(a, b);
        public static BigInteger randint(BigInteger a, BigInteger b) => _inst.randint(a, b);
        public static PyBytes randbytes(long n) => _inst.randbytes(n);
        public static T choice<T>(IEnumerable<T> seq) => _inst.choice(seq);
        public static string choice(string s) => _inst.choice(s);
        public static void shuffle<T>(IList<T> x) => _inst.shuffle(x);
        public static List<T> sample<T>(IEnumerable<T> population, long k) => _inst.sample(population, k);
        public static List<string> sample(string population, long k) => _inst.sample(population, k);
        public static List<T> choices<T>(IEnumerable<T> population, IEnumerable? weights = null, IEnumerable? cum_weights = null, long k = 1) =>
            _inst.choices(population, weights, cum_weights, k);
        public static double uniform(double a, double b) => _inst.uniform(a, b);
        public static double triangular(double low = 0.0, double high = 1.0, double? mode = null) => _inst.triangular(low, high, mode);
        public static double normalvariate(double mu = 0.0, double sigma = 1.0) => _inst.normalvariate(mu, sigma);
        public static double gauss(double mu = 0.0, double sigma = 1.0) => _inst.gauss(mu, sigma);
        public static double lognormvariate(double mu, double sigma) => _inst.lognormvariate(mu, sigma);
        public static double expovariate(double lambd = 1.0) => _inst.expovariate(lambd);
        public static double paretovariate(double alpha) => _inst.paretovariate(alpha);
        public static double weibullvariate(double alpha, double beta) => _inst.weibullvariate(alpha, beta);
        public static double gammavariate(double alpha, double beta) => _inst.gammavariate(alpha, beta);
